package com.nextrade.domain.ledger; import com.nextrade.common.enumtype.LedgerEntryType; import com.nextrade.common.identifier.*; import com.nextrade.common.valueobject.*; public record Deposit(LedgerEntry entry) { public Deposit { if(entry.type()!=LedgerEntryType.DEPOSIT) throw new IllegalArgumentException("Wrong ledger type"); } public static Deposit of(UserId user,Money amount,String reference){ return new Deposit(new LedgerEntry(LedgerEntryId.generate(),user,LedgerEntryType.DEPOSIT,amount,reference,java.time.Instant.now())); } }